const PACK_NODES = {
  contacts: 'Code in JavaScript',
  deals: 'Code in JavaScript1',
  companies: 'Code in JavaScript2',
  custom_fields_clientify: 'Code in JavaScript3',
  conversation_samples: 'Code in JavaScript4',
  manychat_flows: 'Code in JavaScript5',
  manychat_tags: 'Code in JavaScript6',
  manychat_page_info: 'Code in JavaScript7',
  manychat_widgets: 'Code in JavaScript8',
  manychat_custom_fields: 'Code in JavaScript9'
};

function readNodeItems(nodeName) {
  try {
    return $(nodeName).all().map(item => item.json);
  } catch {
    return [];
  }
}

function unwrapDrfPage(page) {
  // Clientify (DRF-style): {count,next,previous,results:[...]} o lista simple
  if (Array.isArray(page)) return page;
  if (page && Array.isArray(page.results)) return page.results;
  if (page && Array.isArray(page.data)) return page.data;
  return [];
}

function unwrapManyChatPage(page) {
  // ManyChat: {status:'success', data: [...] | {...}}
  const d = page && page.data !== undefined ? page.data : page;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return [d];
  return [];
}

function collect(section, unwrapFn) {
  const packItems = readNodeItems(PACK_NODES[section]);
  const pages = packItems.flatMap(item => (item.pages || []));
  return pages.flatMap(unwrapFn);
}

const contacts = collect('contacts', unwrapDrfPage);
const deals = collect('deals', unwrapDrfPage);
const companies = collect('companies', unwrapDrfPage);
const custom_fields_clientify = collect('custom_fields_clientify', unwrapDrfPage);

const manychat_flows = collect('manychat_flows', unwrapManyChatPage);
const manychat_tags = collect('manychat_tags', unwrapManyChatPage);
const manychat_page_info_arr = collect('manychat_page_info', unwrapManyChatPage);
const manychat_widgets = collect('manychat_widgets', unwrapManyChatPage);
const manychat_custom_fields = collect('manychat_custom_fields', unwrapManyChatPage);

const conversation_samples_raw = readNodeItems(PACK_NODES.conversation_samples).flatMap(item => (item.pages || []));

function transcriptRoleLabel(role) {
  if (role === 'human') return 'CLIENTE';
  if (role === 'assistant' || role === 'ai') return 'AGENTE';
  return String(role || 'UNKNOWN').toUpperCase();
}

const conversation_samples = conversation_samples_raw.map(row => {
  const turns = (row.transcript || []).map((m, i) => ({
    turn: i + 1,
    role: m.role,
    speaker: transcriptRoleLabel(m.role),
    text: String(m.content || '').trim()
  }));
  const transcript_text = turns
    .map(m => String(m.turn).padStart(2, '0') + '. ' + m.speaker + ': ' + m.text)
    .join('\n');
  return {
    sample_id: row.sample_id ?? null,
    session_hash: row.session_hash ?? null,
    message_count: Number(row.message_count ?? turns.length),
    human_count: Number(row.human_count ?? 0),
    assistant_count: Number(row.assistant_count ?? 0),
    turns,
    transcript_text,
    raw: row
  };
});

return [
  {
    json: {
      clientify: {
        contacts,
        deals,
        companies,
        custom_fields: custom_fields_clientify
      },
      manychat: {
        page_info: manychat_page_info_arr[0] || {},
        flows: manychat_flows,
        tags: manychat_tags,
        widgets: manychat_widgets,
        custom_fields: manychat_custom_fields
      },
      conversation_samples,
      _metadata: {
        exported_at: new Date().toISOString(),
        source: 'Clientify API v1 + ManyChat API v2 + Supabase Postgres (n8n_chat_histories)',
        counts: {
          clientify_contacts: contacts.length,
          clientify_deals: deals.length,
          clientify_companies: companies.length,
          clientify_custom_fields: custom_fields_clientify.length,
          manychat_flows: manychat_flows.length,
          manychat_tags: manychat_tags.length,
          manychat_widgets: manychat_widgets.length,
